<script setup lang="ts">
import {computed,watch} from 'vue'
import {clockOffset,copyAttendanceRules,offsetClock,offsetNextDay,useRestPolicyText,validAttendanceRules,type AttendanceRules,type BreakRule} from '../restPolicy'
const props=withDefaults(defineProps<{modelValue:AttendanceRules;startTime?:string;duration?:number;disabled?:boolean}>(),{startTime:'11:00',duration:1440,disabled:false})
const emit=defineEmits<{'update:modelValue':[value:AttendanceRules];valid:[value:boolean]}>(),{r}=useRestPolicyText()
const valid=computed(()=>validAttendanceRules(props.modelValue,props.duration))
watch(valid,value=>emit('valid',value),{immediate:true})
function update(change:(rules:AttendanceRules)=>void){if(props.disabled)return;const next=copyAttendanceRules(props.modelValue);change(next);emit('update:modelValue',next)}
function updateBreak(id:string,change:(rule:BreakRule)=>void){update(rules=>{const rule=rules.breaks.find(b=>b.id===id);if(rule)change(rule)})}
function add(){update(rules=>rules.breaks.push({id:crypto.randomUUID(),name:'',mode:'window',startOffset:null,endOffset:null,quotaMinutes:null,punchMode:'none',paid:false}))}
function inputValue(event:Event){return (event.target as HTMLInputElement).value}
function checked(event:Event){return (event.target as HTMLInputElement).checked}
function setClock(b:BreakRule,edge:'startOffset'|'endOffset',time:string){updateBreak(b.id,next=>next[edge]=clockOffset(props.startTime,time,offsetNextDay(props.startTime,b[edge])))}
function setDay(b:BreakRule,edge:'startOffset'|'endOffset',day:boolean){const clock=offsetClock(props.startTime,b[edge]);if(clock)updateBreak(b.id,next=>next[edge]=clockOffset(props.startTime,clock,day))}
function setMode(b:BreakRule,event:Event){updateBreak(b.id,next=>{next.mode=inputValue(event) as BreakRule['mode'];if(next.mode!=='window'&&next.punchMode==='none')next.punchMode='required';if(next.mode!=='quota')next.quotaMinutes=null})}
</script>
<template><div class="wf-attendance-rules"><fieldset :disabled="disabled"><legend>{{r('breaks')}}</legend><div v-for="b in modelValue.breaks" :key="b.id" class="wf-rule-card"><div class="wf-grid"><label>{{r('name')}}<input :value="b.name" maxlength="80" required @input="updateBreak(b.id,next=>next.name=inputValue($event))"></label><label>{{r('mode')}}<select :value="b.mode" @change="setMode(b,$event)"><option v-for="mode in (['window','actual','quota'] as const)" :key="mode" :value="mode">{{r(mode)}}</option></select></label></div><div class="wf-grid"><label>{{r('start')}}<input :value="offsetClock(startTime,b.startOffset)" type="time" :required="b.mode==='window'" @input="setClock(b,'startOffset',inputValue($event))"><span class="wf-check"><input type="checkbox" :checked="offsetNextDay(startTime,b.startOffset)" :disabled="b.startOffset===null" @change="setDay(b,'startOffset',checked($event))">{{r('nextDay')}}</span></label><label>{{r('end')}}<input :value="offsetClock(startTime,b.endOffset)" type="time" :required="b.mode==='window'" @input="setClock(b,'endOffset',inputValue($event))"><span class="wf-check"><input type="checkbox" :checked="offsetNextDay(startTime,b.endOffset)" :disabled="b.endOffset===null" @change="setDay(b,'endOffset',checked($event))">{{r('nextDay')}}</span></label></div><div class="wf-grid"><label v-if="b.mode==='quota'">{{r('quotaMinutes')}}<input :value="b.quotaMinutes" type="number" min="1" :max="duration" required @input="updateBreak(b.id,next=>next.quotaMinutes=inputValue($event)===''?null:Number(inputValue($event)))"></label><label>{{r('punch')}}<select :value="b.punchMode" @change="updateBreak(b.id,next=>next.punchMode=inputValue($event) as BreakRule['punchMode'])"><option v-if="b.mode==='window'" value="none">{{r('none')}}</option><option value="optional">{{r('optional')}}</option><option value="required">{{r('required')}}</option></select></label></div><div class="wf-form-actions"><label class="wf-check"><input type="checkbox" :checked="b.paid" @change="updateBreak(b.id,next=>next.paid=checked($event))">{{r('paid')}}</label><button type="button" @click="update(rules=>rules.breaks=rules.breaks.filter(item=>item.id!==b.id))">{{r('remove')}}</button></div></div><button type="button" @click="add">{{r('add')}}</button><p class="wf-hint">{{r('optionalWindow')}}</p><div class="wf-grid"><label>{{r('late')}}<input :value="modelValue.lateGraceMinutes" type="number" min="0" max="1440" required @input="update(rules=>rules.lateGraceMinutes=Number(inputValue($event)))"></label><label>{{r('early')}}<input :value="modelValue.earlyGraceMinutes" type="number" min="0" max="1440" required @input="update(rules=>rules.earlyGraceMinutes=Number(inputValue($event)))"></label><label>{{r('breakGrace')}}<input :value="modelValue.breakGraceMinutes" type="number" min="0" max="1440" required @input="update(rules=>rules.breakGraceMinutes=Number(inputValue($event)))"></label><label>{{r('graceMode')}}<select :value="modelValue.graceMode" @change="update(rules=>rules.graceMode=inputValue($event) as AttendanceRules['graceMode'])"><option value="full">{{r('full')}}</option><option value="excess">{{r('excess')}}</option></select></label></div><h4>{{r('anomaly')}}</h4><p class="wf-hint">{{r('anomalyHint')}}</p><div v-for="a in modelValue.anomalies" :key="a.code" class="wf-rule-anomaly"><label>{{a.code}}<input :value="a.name" maxlength="80" required @input="update(rules=>{const item=rules.anomalies.find(x=>x.code===a.code);if(item)item.name=inputValue($event)})"></label><label class="wf-check"><input type="checkbox" :checked="a.enabled" @change="update(rules=>{const item=rules.anomalies.find(x=>x.code===a.code);if(item)item.enabled=checked($event)})">{{r('enabled')}}</label><label class="wf-check"><input type="checkbox" :checked="a.affectsBonus" @change="update(rules=>{const item=rules.anomalies.find(x=>x.code===a.code);if(item)item.affectsBonus=checked($event)})">{{r('affectsBonus')}}</label></div><p v-if="!valid" class="wf-rule-error" role="alert">{{r('invalid')}}</p></fieldset></div></template>
<style scoped>
.wf-rule-card{padding:10px;border:1px solid var(--border,#dfe5ed);border-radius:8px;margin-bottom:10px}.wf-rule-anomaly{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin:8px 0}.wf-rule-anomaly>label:first-child{flex:1 1 180px}.wf-rule-anomaly .wf-check{margin:0}.wf-rule-error{color:#b91c1c}.wf-attendance-rules{min-width:0}.wf-attendance-rules fieldset{min-width:0}.wf-attendance-rules h4{margin-bottom:6px}
</style>
